import { IconProps } from '@hexa-ui/icons';

type ConditionalProps =
  | {
      /** Only 'inherit' and 'tertiary' variants apply to size 'tiny' */
      variant?: 'primary' | 'secondary' | 'tertiary' | 'inherit';
      size?: 'small' | 'medium' | 'large';
    }
  | {
      variant: 'tertiary' | 'inherit';
      size?: 'tiny';
    };

export interface IconButtonBaseTypes extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** If `true` elevation shadow will be displayed */
  elevation?: boolean;
  /** If `true` loading dots animation will be displayed */
  loading?: boolean;
  disabled?: boolean;
  /** Set the icon */
  icon: React.FunctionComponent<IconProps>;
  /** onClick function to set actions for the button */
  onClick?(e: React.MouseEvent<HTMLButtonElement>): void;
}

export type IconButtonTypes = ConditionalProps & IconButtonBaseTypes;
